};

const pathPattern = /^(?:this|@index)(?:\.[A-Za-z_$][\w$]*|\.\d+)*$|^[A-Za-z_$][\w$]*(?:\.[A-Za-z_$][\w$]*|\.\d+)*$/;

function positionAt(source: string, offset: number): Position {
  let line = 1;
  let column = 1;
